parameters.jsonBody:
={{ JSON.stringify({
  chat_id: $('Set | Telegram Input | NormalizeInput').item.json.chatId,
  text: 'Привет. Нажми /questions, выбери вопрос и ответь на него текстом или голосом. Если ответ будет слишком коротким, я задам уточнение.'
}) }}

={{ JSON.stringify({
  chat_id: $('Set | Telegram Input | NormalizeInput').item.json.chatId,
  text: 'Выбери вопрос для ответа. Ниже только вопросы, на которые ещё нет сохранённого ответа:',
  reply_markup: {
    inline_keyboard: $items('Set | BD_ProfileQuestions | Question Message | ShowQuestions').map(item => [{
      text: `${item.json.sortOrder}. ${item.json.questionText}`,
      callback_data: `question:${item.json.questionId}`
    }])
  }
}) }}

={{ JSON.stringify({
  chat_id: $('Set | Telegram Input | NormalizeInput').item.json.chatId,
  text: `Вопрос выбран:

${$('Search | BD_ProfileQuestions | Selected Question | SelectQuestion').item.json.questionText}

Ответь одним сообщением: текстом или голосом.`
}) }}

={{ JSON.stringify({
  chat_id: $('Set | Telegram Answer | User Reply | NormalizeAnswer').item.json.chatId,
  text: 'Сначала выбери вопрос через /questions, потом пришли ответ текстом или голосом.'
}) }}

={{ JSON.stringify({
  chat_id: $('Set | Telegram Answer | User Reply | NormalizeAnswer').item.json.chatId,
  text: 'Ответ сохранён. Можешь выбрать следующий вопрос через /questions.'
}) }}

